    <div className="studio-app">
      <StudioHeader />
      <div className="studio-layout">
        <CanvasTabs />
        <ChatCopilot />
      </div>
      <Toasts />
    </div>
  );
}

function StudioShellFull() {
  return (
    <div className="studio-app">
      <SettingsPanel />
      <StudioHeader />
      <div className="studio-layout">
        <CanvasTabs />
        <ChatCopilot />
      </div>
      <Toasts />
    </div>
  );
}

